pub fn primes_up_to(n: u32) -> Vec<u32> {
    let mut is_prime = vec![true; (n as f64).sqrt() as u32 + 1];
    let mut primes: Vec<u32> = Vec::new();

    for (i, &is_prime) in is_prime.iter().enumerate().take((n as f64).sqrt() as u32 + 1).enumerate() {
        if is_prime {
            primes.push(i as u32 + 1);
            for j in (0..is_prime as f64).floor() as usize..=((n as f64).sqrt() as u32).ceil() {
                let mut k = (j..=is_prime as f64.sqrt()).step_by(is_prime as f64).take(is_prime as usize);
                if k.any(|&x| x > n) {
                    break;
                }
                is_prime[k.all(|&x| !is_prime[x as usize - 1])];
            }
        }
    }

    if is_prime[(n as f64).sqrt() as u32] {
        primes.push(n as u32 + 1);
    }

    primes.sort();
    primes
}

