    let out = s.chars().map(|c| {
        let offset = (lower.find(c).unwrap_or(0) + shift as usize) % alphabet.len();
        if c.is_ascii_lowercase() {
            lower[offset]
        } else if c.is_ascii_uppercase() {
            upper[offset]
        } else {
            c
        }
    }).collect::<String>();
    out
}

